Chapter 'farming' 'Farming' 'minecraft:wheat' 'magic' 'Crops, livestock, food and a dependable farm.' -showlines
Q 'start' 'From Dirt to Dinner' 'check' '' 'xp:50' -icon 'minecraft:book' -desc 'Build a reliable food supply with crops, animals and useful infrastructure. This chapter is independent of the Productive and Mystical Agriculture chapters.'
Q 'wheat' 'A Field of Wheat' 'minecraft:wheat' 'start' 'xp:50' -desc 'Plant seeds on hydrated farmland with enough light and harvest mature wheat.'
Q 'bread' 'Fresh Bread' 'minecraft:bread*3' 'wheat' 'xp:50' -desc 'GSPack allows three wheat anywhere in the crafting grid to make bread.'
Q 'hay' 'Store the Harvest' 'minecraft:hay_block' 'wheat' 'xp:50' -desc 'Compress surplus wheat into hay bales for storage and animal care.'
Q 'beetroot' 'Beetroot Beds' 'minecraft:beetroot' 'wheat' 'xp:50' -opt -desc 'Grow beetroot and save seeds for the next planting.'
Q 'carrots' 'Carrot Patch' 'minecraft:carrot' 'start' 'xp:50' -desc 'Find carrots and grow them on farmland. Reserve some for replanting and animal breeding.'
Q 'potatoes' 'Potato Patch' 'minecraft:potato' 'carrots' 'xp:50' -desc 'Grow potatoes as a dependable crop. Poisonous potatoes are not required.'
Q 'baked' 'A Warm Meal' 'minecraft:baked_potato*8' 'potatoes' 'xp:50' -desc 'Cook your potatoes before eating them.'
Q 'pumpkin' 'Pumpkin Patch' 'minecraft:pumpkin' 'carrots' 'xp:50' -desc 'Give the stem an empty adjacent block for its fruit.'
Q 'melon' 'Melon Harvest' 'minecraft:melon_slice*8' 'pumpkin' 'xp:50' -desc 'Melons are useful food, compost and brewing ingredients.'
Q 'sugar' 'Sugar Cane Bank' 'minecraft:sugar_cane*8' 'start' 'xp:50' -desc 'Plant sugar cane beside water for paper and sugar.'
Q 'kelp' 'Underwater Crops' 'minecraft:kelp*8' 'sugar' 'xp:50' -opt -desc 'Grow kelp in water. Dried kelp can be used as food or fuel.'
Q 'cocoa' 'Cocoa Grove' 'minecraft:cocoa_beans*8' 'sugar' 'xp:50' -opt -desc 'Cocoa grows on jungle logs. Replant a few beans before crafting with them.'
Q 'compost' 'Waste into Growth' 'minecraft:composter' 'wheat' 'xp:50' -desc 'Compost surplus plants and seeds into bone meal.'
Q 'bone_meal' 'A Helping Hand' 'minecraft:bone_meal*8' 'compost' 'xp:50' -desc 'Bone meal speeds up many crops. Keep enough light and water available.'
Q 'cows' 'Cattle Supplies' 'minecraft:milk_bucket' 'start' 'xp:50' -desc 'Bring cows into an enclosure. Use wheat to breed them and a bucket to collect milk. This quest detects the milk, not the enclosure.'
Q 'leather' 'Leather Supply' 'minecraft:leather*4' 'cows' 'xp:50' -desc 'Collect leather for books and equipment.'
Q 'chickens' 'A Basket of Eggs' 'minecraft:egg*8' 'cows' 'xp:50' -desc 'Keep chickens and collect eggs. Seeds can be used for breeding.'
Q 'sheep' 'Wool Supply' 'minecraft:white_wool*8' 'cows' 'xp:50' -desc 'Breed and shear sheep for renewable wool.'
Q 'orchard' 'An Apple a Day' 'minecraft:apple*4' 'start' 'xp:50' -desc 'Collect apples and plant trees near your base. Productive Trees provides a dedicated breeding chapter.'
Q 'bees' 'Pollinator Supplies' 'minecraft:beehive' 'orchard' 'xp:50' -desc 'Build a vanilla beehive and provide flowers. Bees can help nearby crops; Productive Bees remains optional.'
Q 'honey' 'A Little Honey' 'minecraft:honey_bottle' 'bees' 'xp:50' -desc 'Collect honey carefully, using a campfire when appropriate.'
Q 'automation' 'Farm Infrastructure' 'minecraft:hopper;minecraft:chest' 'compost' 'xp:50' -desc 'Hoppers and storage collect produce. Pylons and Productive Farming have further automation options in their own chapters.'
Q 'pistons' 'Moving Harvests' 'minecraft:piston;minecraft:observer' 'automation' 'xp:50' -opt -desc 'Observers and pistons can automate suitable crops such as sugar cane. Check your design before leaving it running.'
Q 'pantry' 'A Stocked Pantry' 'minecraft:bread*8;minecraft:baked_potato*8;minecraft:carrot*8' 'bread,baked,automation' 'xp:150;table:uncommon' -desc 'Keep a varied food reserve for exploration. Finishing this chapter contributes to Farming mastery.'

Chapter 'hunting' 'Mob Hunting Board' 'minecraft:iron_sword' 'explore' 'One-time contracts for overworld, Nether and End threats.' -showlines
Q 'start' 'Accept a Contract' 'check' '' 'xp:50' -icon 'minecraft:book' -desc 'These one-time bounties count player kills after the task is active. Team progress is shared. Prepare equipment and choose a branch; no other chapter is required.'
